//! Rathole runs inside the PortHub process. No executable extraction, child
//! process, or additional tunnel listener is required.
pub mod client_plan;
pub mod websocket;

use anyhow::{Context, Result};
use std::path::PathBuf;

pub use rathole::{
    Config, EmbeddedClient, EmbeddedServer, FramedIo, TunnelIo, DIRECT_FRAME_SIZE, SUBPROTOCOL,
    WEBSOCKET_FRAME_SIZE,
};

/// Accept the gateway configuration already generated by PortHub. Its embedded
/// server intentionally has no standalone communication bind address.
pub fn gateway_config(input: &str) -> Result<Config> {
    let mut value: toml::Value = toml::from_str(input)?;
    let server = value
        .get_mut("server")
        .and_then(toml::Value::as_table_mut)
        .ok_or_else(|| anyhow::anyhow!("missing server configuration"))?;
    server
        .entry("bind_addr")
        .or_insert_with(|| toml::Value::String("127.0.0.1:0".into()));
    let config = Config::from_str(&toml::to_string(&value)?)?;
    let mut binds = std::collections::HashSet::new();
    if let Some(server) = &config.server {
        for service in server.services.values() {
            let bind: std::net::SocketAddr = service.bind_addr.parse()?;
            if !binds.insert(bind) {
                anyhow::bail!("duplicate service bind address");
            }
        }
    }
    Ok(config)
}

pub async fn run_client(config: PathBuf) -> Result<()> {
    run_client_until(config, async {
        let _ = tokio::signal::ctrl_c().await;
    })
    .await
}

pub async fn run_client_until(
    config: PathBuf,
    stop: impl std::future::Future<Output = ()>,
) -> Result<()> {
    use notify::{RecursiveMode, Watcher};
    let config = if config.is_absolute() {
        config
    } else {
        std::env::current_dir()?.join(config)
    };
    let parent = config
        .parent()
        .context("configuration must have a parent directory")?;
    let target = config.clone();
    let (events, mut changes) = tokio::sync::mpsc::channel(1);
    let mut watcher =
        notify::recommended_watcher(move |event: notify::Result<notify::Event>| match event {
            Ok(event)
                if matches!(
                    event.kind,
                    notify::EventKind::Create(_)
                        | notify::EventKind::Modify(_)
                        | notify::EventKind::Remove(_)
                ) && event
                    .paths
                    .iter()
                    .any(|path| path.file_name() == target.file_name()) =>
            {
                let _ = events.try_send(());
            }
            Err(error) => {
                tracing::warn!("configuration watcher reported an error");
                tracing::debug!(%error,"configuration watcher details");
            }
            _ => {}
        })?;
    // Watch the directory before the initial read, including atomic rename,
    // delete/recreate and platform-specific editor save events. Coalesce bursts.
    watcher.watch(parent, RecursiveMode::NonRecursive)?;
    let mut previous = tokio::fs::read_to_string(&config)
        .await
        .context("read client configuration")?;
    let mut selected = client_plan::ClientPlan::parse(&previous)?
        .choose(std::time::Duration::from_secs(2))
        .await;
    let mut client = EmbeddedClient::new(selected.config.clone()).await?;
    tokio::pin!(stop);
    loop {
        tokio::select! {
            _=&mut stop=>break,
            event=changes.recv()=>{
                if event.is_none() {client.shutdown().await;anyhow::bail!("configuration watcher stopped");}
                let candidate=async {
                    let content=tokio::fs::read_to_string(&config).await?;
                    if content!=previous {
                        let plan=client_plan::ClientPlan::parse(&content)?;
                        let next=match plan.candidates.iter().find(|candidate|candidate.endpoint==selected.endpoint && candidate.kind==selected.kind && candidate.config.client.as_ref().map(|c|&c.transport)==selected.config.client.as_ref().map(|c|&c.transport)){
                            Some(candidate)=>candidate.clone(),None=>plan.choose(std::time::Duration::from_secs(2)).await,
                        };
                        client.reload(next.config.clone()).await?;
                        selected=next;previous=content;
                    }
                    Ok::<_,anyhow::Error>(())
                }.await;
                if let Err(error)=candidate {
                    tracing::warn!("configuration reload rejected; retaining current services");
                    tracing::debug!(%error,"configuration reload details");
                }
            },
        }
    }
    client.shutdown().await;
    Ok(())
}
